const pages: Page[] = ['workspace', 'users', 'roles', 'login']
const page = ref<Page>(pages.includes(params.get('page') as Page) ? params.get('page') as Page : 'workspace')
const dark = ref(params.get('theme') === 'dark'), english = ref(params.get('lang') === 'en')
const tone = ref('iris'), mobile = ref(false), search = ref(''), status = ref('all'), period = ref('week')
const selected = ref<string[]>([]), role = ref(1), toast = ref(''), invite = ref<HTMLDialogElement>()
const t = (zh: string, en: string) => english.value ? en : zh
