  { id: 'roles' as Page, icon: ShieldCheck, label: t('角色与权限', 'Roles & access') },
  { id: 'login' as Page, icon: LogIn, label: t('登录页预览', 'Sign-in preview') },
])
const title = computed(() => nav.value.find(n => n.id === page.value)?.label)
watch([dark, tone, english], () => {
