  document.documentElement.dataset.tone = tone.value
  document.documentElement.lang = english.value ? 'en' : 'zh-CN'
}, { immediate: true })
function go(id: Page) { page.value = id; mobile.value = false; const url = new URL(location.href); url.searchParams.set('page', id); history.replaceState(null, '', url) }
function scrollTasks() { document.getElementById('tasks')?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' }) }
async function focusSearch() { go('users'); await nextTick(); document.getElementById('member-search')?.focus() }
function keyboard(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); void focusSearch() }; if (event.key === 'Escape') mobile.value = false }
onMounted(() => window.addEventListener('keydown', keyboard))
onUnmounted(() => { window.removeEventListener('keydown', keyboard); clearTimeout(timer) })
let timer: ReturnType<typeof setTimeout>
function notify(message = t('这是设计演示，未提交任何业务数据。', 'Design demo only. No business data was submitted.')) { toast.value = message; clearTimeout(timer); timer = setTimeout(() => toast.value = '', 4000) }
const people = [
  { id: '01', name: '林知夏', en: 'Zixia Lin', initials: 'LX', email: 'lin.zixia@example.test', department: ['产品设计', 'Product design'], role: ['管理员', 'Administrator'], active: true, time: '09:42', color: 'lavender' },
  { id: '02', name: '陈序', en: 'Xu Chen', initials: 'CX', email: 'chen.xu@example.test', department: ['研发中心', 'Engineering'], role: ['开发者', 'Developer'], active: true, time: '09:35', color: 'mint' },
  { id: '03', name: '周予安', en: 'Yuan Zhou', initials: 'ZA', email: 'zhou.yuan@example.test', department: ['运营中心', 'Operations'], role: ['运营成员', 'Operator'], active: true, time: '09:18', color: 'peach' },
  { id: '04', name: '许星遥', en: 'Xingyao Xu', initials: 'XY', email: 'xu.xingyao@example.test', department: ['产品设计', 'Product design'], role: ['普通成员', 'Member'], active: true, time: '08:56', color: 'blue' },
  { id: '05', name: '沈亦舟', en: 'Yizhou Shen', initials: 'SZ', email: 'shen.yizhou@example.test', department: ['研发中心', 'Engineering'], role: ['开发者', 'Developer'], active: false, time: t('昨日', 'Yesterday'), color: 'pink' },
  { id: '06', name: '陆清和', en: 'Qinghe Lu', initials: 'LH', email: 'lu.qinghe@example.test', department: ['运营中心', 'Operations'], role: ['普通成员', 'Member'], active: true, time: '08:30', color: 'sand' },
]
const filtered = computed(() => people.filter(p => `${p.name} ${p.en} ${p.email}`.toLowerCase().includes(String(search.value).toLowerCase()) && (status.value === 'all' || (status.value === 'active') === p.active)))
const roles = computed(() => [t('超级管理员', 'Super administrator'), t('运营管理员', 'Operations admin'), t('开发者', 'Developer'), t('普通成员', 'Member')])
const permissionSets = ref([[true, true, true, true, true, true, true, true], [true, true, false, false, true, true, true, false], [true, false, false, false, true, false, true, false], [true, false, false, false, false, false, true, false]])
const checkedCount = computed(() => permissionSets.value[role.value]?.filter(Boolean).length || 0)
const groups = computed(() => [
  { icon: Users, title: t('用户与组织', 'People & organization'), description: t('管理团队成员与组织资料', 'Manage members and organization details'), labels: [t('查看用户', 'View people'), t('创建用户', 'Create people'), t('编辑用户', 'Edit people'), t('停用用户', 'Deactivate people')] },
  { icon: Folder, title: t('内容与协作', 'Content & collaboration'), description: t('管理通知、文件与协作内容', 'Manage notices, files and shared content'), labels: [t('查看文件', 'View files'), t('发布通知', 'Publish notices'), t('查看消息', 'View messages'), t('删除文件', 'Delete files')] },
])
const tasks = computed(() => [
  [t('确认新成员的访问权限', 'Review new member access'), t('身份与访问', 'Identity & access'), t('优先处理', 'Priority'), 'warning'],
  [t('更新本周团队公告', 'Update the weekly announcement'), t('消息中心', 'Message center'), t('今日截止', 'Due today'), 'neutral'],
  [t('检查开放接口应用配置', 'Review API application settings'), t('开放平台', 'Open platform'), t('待确认', 'To review'), 'neutral'],
])
const series = computed(() => period.value === 'week' ? [238, 312, 276, 410, 465, 531, 614] : Array.from({ length: 30 }, (_, i) => Math.round(180 + i * 13 + Math.sin(i) * 45)))
const chartTotal = computed(() => new Intl.NumberFormat('en-US').format(series.value.reduce((a,b) => a+b, 0)))
const chartPoints = computed(() => series.value.map((value,i) => `${i * 500 / (series.value.length-1)},${160-value/5}`).join(' '))
</script>

