        </template>

        <template v-if="page === 'roles'">
          <div class="page-heading"><div><div class="eyebrow">THE RIGHT ACCESS, BY DESIGN</div><h1>{{ t('权限有界，协作无间。', 'Clear access. Confident teams.') }}</h1><p>{{ t('把恰当的权限，交给恰当的人。', 'Give the right people the right level of access.') }}</p></div><Button variant="outline" @click="notify()"><Plus :size="16" />{{ t('新建角色', 'New role') }}</Button></div><div class="role-layout"><section class="surface role-list"><div class="section-heading"><h2>{{ t('全部角色', 'All roles') }}</h2><span class="count-chip">4</span></div><button v-for="(r,i) in roles" :key="i" :class="['role-item', { selected: role === i }]" @click="role = i"><span class="role-icon"><ShieldCheck :size="18" /></span><span><b>{{ r }}</b><small>{{ [2,12,8,106][i] }} {{ t('位成员', 'members') }}</small></span><ChevronRight :size="14" /></button><div class="role-hint"><ShieldCheck :size="18" /><p>{{ t('清晰的角色边界，是安全协作的开始。', 'Clear role boundaries make safe collaboration possible.') }}</p></div></section><section class="surface permission-panel"><div class="permission-heading"><div><span class="badge accent">{{ t('角色配置', 'ROLE SETTINGS') }}</span><h2>{{ roles[role] }}</h2><p>{{ t('负责日常内容运营与团队协作。权限修改仅在本预览内生效。','Configure access for daily operations. Changes stay in this preview.') }}</p></div><span class="permission-emblem"><ShieldCheck :size="32" /></span></div><div class="permission-meta"><span>{{ t('权限范围', 'Permission scope') }}</span><span>{{ t(`已选择 ${checkedCount} 项`, `${checkedCount} selected`) }}</span></div><div v-for="(group,g) in groups" :key="g" class="permission-group"><div class="group-title"><span class="group-icon"><component :is="group.icon" :size="18" /></span><div><h3>{{ group.title }}</h3><p>{{ group.description }}</p></div><span class="count-chip">{{ permissionSets[role]?.slice(g*4,g*4+4).filter(Boolean).length }}/4</span></div><div class="permission-options"><label v-for="(label,i) in group.labels" :key="i"><input v-model="permissionSets[role]![g*4+i]" type="checkbox"><span>{{ label }}</span></label></div></div><div class="permission-footer"><span><span class="tiny-dot"></span>{{ t('设计演示 · 本地临时修改', 'Design demo · temporary local changes') }}</span><Button @click="notify(t('预览已保存；未调用真实权限接口。','Preview saved; no permission API was called.'))"><Check :size="16" />{{ t('保存权限', 'Save permissions') }}</Button></div></section></div>
        </template>
        <footer class="app-footer"><span class="footer-brand">modulith<span>.</span><small>BUILT TO GROW.</small></span><span class="footer-right"><span class="status-dot"></span>{{ t('演示环境', 'Demo environment') }}<span class="footer-divider">/</span>v0.1 · {{ t('柔光工作空间', 'Softlight workspace') }}</span></footer>
      </main>
    </div>
  </div>
  <dialog ref="invite" class="invite-dialog"><form @submit.prevent="invite?.close(); notify(t('成员表单演示完成，未创建真实账号。','Member form preview complete; no account was created.'))"><div class="section-heading"><h2>{{ t('邀请新的可能', 'Make room for someone new') }}</h2><button type="button" :aria-label="t('关闭','Close')" @click="invite?.close()"><X :size="20" /></button></div><p>{{ t('这是一张表单视觉样板，不发送邀请。','A visual form sample. No invitation will be sent.') }}</p><label for="new-name">{{ t('成员姓名','Name') }}</label><Input id="new-name" required :placeholder="t('示例姓名','Sample name')" /><label for="new-email">{{ t('邮箱','Email') }}</label><Input id="new-email" required type="email" placeholder="name@example.test" /><Button type="submit">{{ t('预览完成','Finish preview') }}<ArrowRight :size="16" /></Button></form></dialog>
  <div v-if="toast" class="toast" role="status"><span class="note-icon"><Check :size="16" /></span>{{ toast }}<button :aria-label="t('关闭提示','Dismiss message')" @click="toast = ''"><X :size="16" /></button></div>
</template>
